environment.fix:
F=$HOME/.config/modernization/env && D=$HOME/.config/modernization/data.env && umask 077 && touch "$D" && chmod 600 "$D" && pw=$(sed -n 's|^export MP_DATA_PG_URL=postgresql://postgres:\([0-9a-f]*\)@127\.0\.0\.1:55432$|\1|p' "$D") && { test -n "$pw" || pw=$(openssl rand -hex 24); } && rp=$(sed -n 's|^export MP_RUNNER_PG_URL=postgresql://mp_runner:\([0-9a-f]*\)@127\.0\.0\.1:55432$|\1|p' "$D") && { test -n "$rp" || rp=$(openssl rand -hex 24); } && { grep -Ev '^export (MP_DATA_PG_URL|MP_RUNNER_PG_URL)=' "$D"; echo "export MP_DATA_PG_URL=postgresql://postgres:$pw@127.0.0.1:55432"; echo "export MP_RUNNER_PG_URL=postgresql://mp_runner:$rp@127.0.0.1:55432"; } > "$D.new" && mv "$D.new" "$D" && (docker start mp-pg16 2>/dev/null || POSTGRES_PASSWORD=$pw docker run -d --name mp-pg16 --restart unless-stopped -e POSTGRES_PASSWORD -p 127.0.0.1:55432:5432 -v mp-pg16:/var/lib/postgresql/data postgres:16.15@sha256:ca0bd484cb98bf4b24eb1010e73fb3fcbd6714d240fbc1a10eea5b7dbecb641d) && timeout 120 sh -c 'until docker exec mp-pg16 pg_isready -h 127.0.0.1 -U postgres -q; do :; done' && printf "alter role postgres password '%s';
" "$pw" | docker exec -i mp-pg16 psql -U postgres -v ON_ERROR_STOP=1 -q && { docker exec mp-pg16 psql -U postgres -qAtc "select 1 from pg_roles where rolname = 'mp_agent'" | grep -qx 1 || docker exec mp-pg16 psql -U postgres -v ON_ERROR_STOP=1 -qc 'create role mp_agent'; } && docker exec mp-pg16 psql -U postgres -v ON_ERROR_STOP=1 -qc "alter role mp_agent login createdb nosuperuser nocreaterole password 'mp-agent'" && { docker exec mp-pg16 psql -U postgres -qAtc "select 1 from pg_roles where rolname = 'mp_runner'" | grep -qx 1 || docker exec mp-pg16 psql -U postgres -v ON_ERROR_STOP=1 -qc 'create role mp_runner'; } && printf "alter role mp_runner login createdb nosuperuser nocreaterole password '%s';
" "$rp" | docker exec -i mp-pg16 psql -U postgres -v ON_ERROR_STOP=1 -q && docker exec -u postgres mp-pg16 sh -c 'f="$PGDATA/pg_hba.conf" && L=$(printf "%s
" "host /^mpdata_ mp_agent all reject" "host postgres,/^mpdata_ mp_runner all scram-sha-256" "host all mp_runner all reject" "host all all 127.0.0.1/32 scram-sha-256" "host all all ::1/128 scram-sha-256") && { printf "%s
" "$L"; grep -vxF -e "$L" "$f" || test $? -eq 1; } > "$f.new" && cat "$f.new" > "$f" && rm "$f.new"' && docker exec mp-pg16 psql -U postgres -qAtc 'select pg_reload_conf()' | grep -qx t && docker exec mp-pg16 psql -U postgres -qAtc 'select count(*) from pg_hba_file_rules where error is not null' | grep -qx 0 && { docker exec mp-pg16 psql -U postgres -qAtc "select 1 from pg_database where datname = 'mpdata_probe'" | grep -qx 1 || docker exec mp-pg16 createdb -U postgres mpdata_probe; } && { grep -v '^export PG_URL=' "$F"; echo 'export PG_URL=postgresql://mp_agent:mp-agent@127.0.0.1:55432'; } > "$F.new" && mv "$F.new" "$F"
